<?php require 'config.php';require 'auth.php';requireLogin();$pageTitle='Edit Kategori';$id=(int)($_GET['id']??0);$c=read_data('categories');$idx=find_index($c,$id);if($idx===null)redirect('categories.php');if($_SERVER['REQUEST_METHOD']==='POST'){$c[$idx]['name']=trim($_POST['name']??'');$c[$idx]['description']=trim($_POST['description']??'');write_data('categories',$c);$_SESSION['flash']=['type'=>'success','message'=>'Kategori berhasil diperbarui.'];redirect('categories.php');}$_POST=$c[$idx];include 'header.php';?><section class="page-heading"><div><h1>Edit Kategori</h1></div></section><div class="form-card"><form method="post"><div class="form-group"><label>Nama Kategori</label><input name="name" value="<?=e($_POST['name'])?>" required></div><div class="form-group"><label>Deskripsi</label><textarea name="description"><?=e($_POST['description'])?></textarea></div><div class="form-actions"><button class="btn btn-primary">Update</button><a class="btn btn-secondary" href="categories.php">Batal</a></div></form></div><?php include 'footer.php';?>